package wtf.metio.yosql.example.common;

/**
 * What the examples check, rather than what they print.
 *
 * <p>These run as an application per build tool rather than as JUnit tests, because the point is
 * that code generated by Maven, Gradle, Ant or the CLI behaves the same — and only one of those is
 * a Maven module that surefire would reach. A plain main method is the only harness all four
 * share.</p>
 *
 * <p>So the checks say so themselves. A failure exits non-zero, which is what every one of those
 * build tools reads.</p>
 */
public final class Verify {

    private static final System.Logger LOG = System.getLogger(Verify.class.getName());

    public static void that(final boolean condition, final String what) {
        if (!condition) {
            fail(what);
        }
    }

    public static void equal(final Object expected, final Object actual, final String what) {
        if (!expected.equals(actual)) {
            // Two values that print the same and are not equal are a boxed int against a boxed
            // long, near enough every time. Saying only "expected 6, got 6" sends the reader
            // looking at the query instead of at the literal.
            final var detail = String.valueOf(expected).equals(String.valueOf(actual))
                    ? "expected %s (%s), got %s (%s)".formatted(expected, expected.getClass().getSimpleName(),
                            actual, actual.getClass().getSimpleName())
                    : "expected %s, got %s".formatted(expected, actual);
            fail("%s: %s".formatted(what, detail));
        }
    }

    /**
     * For the cases where the generator's contract is that something is refused — a statement
     * returning one row that finds several, say. Passing quietly when nothing is thrown is how a
     * check like that stops checking.
     */
    public static void throwsException(final Runnable action, final String what) {
        try {
            action.run();
        } catch (final RuntimeException expected) {
            return;
        }
        fail("%s: expected it to fail, and it did not".formatted(what));
    }

    private static void fail(final String what) {
        LOG.log(System.Logger.Level.ERROR, "FAILED - {0}", what);
        System.exit(1);
    }

    private Verify() {
        // utility class
    }

}
